// Normalize Twilio webhook payload into a standard lead event
// Twilio sends form-encoded params: From, To, Body (SMS) or CallStatus (voice status callback)
const body = $input.first().json || {};
const from = body.From || body.from || '';
const to = body.To || body.to || '';
const text = body.Body || body.body || '';
const callStatus = body.CallStatus || body.callStatus || '';
const cfg = $('CONFIG — Business Settings').first().json;

// Missed-call statuses from Twilio voice status callbacks
const missed = ['no-answer', 'busy', 'failed', 'canceled', 'cancelled'];
let event_type = 'unknown';
if (text) {
  event_type = 'sms';
} else if (callStatus) {
  event_type = missed.includes(String(callStatus).toLowerCase()) ? 'missed_call' : 'call_status';
}
return [{ json: {
  phone: from,
  twilio_number: to,
  message: text,
  call_status: callStatus,
  event_type,
  first_seen: new Date().toISOString(),
}}];

// Stop if this caller was already texted within the last 24h (no double-texting)
const cfg = $('CONFIG — Business Settings').first().json;
const rows = $('Read Conversation Log — Missed Call').all().map(i => i.json);
const phone = $('Normalize Twilio Payload').first().json.phone;
const windowHrs = parseInt(cfg.nudge_hours || '2', 10) * 12; // 24h when nudge_hours=2
const cutoff = Date.now() - windowHrs * 3600 * 1000;
const recent = rows.filter(r => {
  const p = String(r['Phone'] || '').trim();
  if (!p || p !== String(phone).trim()) return False;
  const st = String(r['Status'] || '');
  if (!['NEW', 'CONTACTED', 'REPLIED', 'NUDGED'].includes(st)) return False;
  const t = new Date(r['Last Updated'] || r['Date'] || 0).getTime();
  return !isNaN(t) && t >= cutoff;
});
return [{ json: {
  phone,
  first_seen: $('Normalize Twilio Payload').first().json.first_seen,
  already_texted: recent.length > 0,
  last_message: '',
}}];

// Rebuild the conversation history from the Sheets log + the new inbound SMS
const rows = $('Read Conversation Log — Lookup').all().map(i => i.json);
const inbound = $('Normalize Twilio Payload').first().json;
const phone = inbound.phone;
const row = rows.find(r => String(r['Phone'] || '').trim() === String(phone).trim()) || {};
let history = [];
try { history = JSON.parse(row['Conversation'] || '[]'); } catch (e) { history = []; }
if (!Array.isArray(history)) history = [];
history.push({ role: 'user', content: inbound.message });
return [{ json: {
  phone,
  message: inbound.message,
  history_json: JSON.stringify(history),
  history_count: history.length,
  last_message: inbound.message,
}}];

