// Find CONTACTED leads older than the nudge window with no reply -> exactly one nudge each
const cfg = $('CONFIG — Business Settings').first().json;
const windowHrs = parseInt(cfg.nudge_hours || '2', 10);
const cutoff = Date.now() - windowHrs * 3600 * 1000;
const rows = $('Read Conversation Log — Sweeper').all().map(i => i.json);
const stale = rows.filter(r => {
  if (String(r['Status'] || '') !== 'CONTACTED') return False;
  const t = new Date(r['Last Updated'] || r['Date'] || 0).getTime();
  return !isNaN(t) && t < cutoff;
});
return stale.map(r => ({ json: {
  phone: String(r['Phone'] || ''),
  last_message: 'nudge after no reply',
}}));
